     2→
     3→import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
     4→import { toast } from "sonner";
     5→
     6→import { authClient } from "@/lib/auth-client";
     7→
     8→import type { Invitation, MemberRole } from "../types";
     9→
    10→/**
    11→ * Fetches the list of invitations for the current organization.
    12→ */
    13→export function useInvitations() {
    14→	const query = useQuery({
    15→		queryKey: ["organization", "invitations"],
    16→		queryFn: async () => {
    17→			const response = await authClient.organization.listInvitations();
    18→			return (response.data ?? []) as Invitation[];
    19→		},
    20→	});
    21→
    22→	return {
    23→		invitations: query.data ?? [],
    24→		isLoading: query.isLoading,
    25→		error: query.error ?? null,
    26→		refetch: query.refetch,
    27→	};
    28→}
    29→
    30→/**
    31→ * Mutation to invite a new member to the organization.
    32→ */
    33→export function useInviteMember() {
    34→	const queryClient = useQueryClient();
    35→
    36→	return useMutation({
    37→		mutationFn: async ({
    38→			email,
    39→			role,
    40→		}: {
    41→			email: string;
    42→			role: MemberRole;
    43→		}) => {
    44→			await authClient.organization.inviteMember({
    45→				email,
    46→				role,
    47→			});
    48→		},
    49→		onSuccess: () => {
    50→			queryClient.invalidateQueries({
    51→				queryKey: ["organization", "invitations"],
    52→			});
    53→			toast.success("Invitation sent successfully");
    54→		},
    55→		onError: (error: Error) => {
    56→			toast.error(error.message || "Failed to send invitation");
    57→		},
    58→	});
    59→}
    60→
    61→/**
    62→ * Mutation to cancel a pending invitation.
    63→ */
    64→export function useCancelInvitation() {
    65→	const queryClient = useQueryClient();
    66→
    67→	return useMutation({
    68→		mutationFn: async ({ invitationId }: { invitationId: string }) => {
    69→			await authClient.organization.cancelInvitation({
