"use client";

import Link from "next/link";
import { Mail } from "lucide-react";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { toast } from "sonner";
import z from "zod";

import { authClient } from "@/lib/auth-client";
import { FormField } from "@/components/forms/form-field";
import {
	Card,
	CardContent,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import Loader from "@/components/loader";

export default function ForgotPasswordPage() {
	const router = useRouter();
	const [email, setEmail] = useState("");
	const [isSubmitting, setIsSubmitting] = useState(false);
	const [isSuccess, setIsSuccess] = useState(false);
	const [error, setError] = useState("");

	const handleSubmit = async (e: React.FormEvent) => {
		e.preventDefault();
		setError("");

		// Validate email
		const emailSchema = z.string().email("Invalid email address");
		const validationResult = emailSchema.safeParse(email);

		if (!validationResult.success) {
			setError(validationResult.error.issues[0].message);
			return;
		}

		setIsSubmitting(true);

		const redirectTo = `${window.location.origin}/reset-password`;

		await authClient.requestPasswordReset(
			{ email, redirectTo },
			{
				onSuccess: () => {
					setIsSuccess(true);
					toast.success("Check your email for the reset link");
				},
				onError: (ctx: { error: { message?: string } }) => {
					setError(
						ctx.error.message || "Failed to send reset email. Please try again.",
					);
					toast.error(ctx.error.message || "Failed to send reset email");
				},
			},
		);

		setIsSubmitting(false);
	};

	if (isSubmitting) {
		return (
			<Card>
				<CardContent className="flex items-center justify-center py-12">
					<Loader />
				</CardContent>
			</Card>
		);
	}

	if (isSuccess) {
		return (
			<Card>
				<CardHeader className="text-center">
					<div className="flex justify-center">
						<Mail className="text-primary size-12" />
					</div>
					<CardTitle className="mt-4">Check Your Email</CardTitle>
					<CardDescription>
						We've sent a password reset link to <strong>{email}</strong>. The
						link will expire in 24 hours.
					</CardDescription>
				</CardHeader>
				<CardContent className="space-y-4">
					<Link href="/sign-in" as={never}>
						<Button variant="outline" className="w-full">
							Back to Sign In
						</Button>
					</Link>
				</CardContent>
			</Card>
		);
	}

	return (
		<Card>
			<CardHeader>
				<CardTitle className="text-2xl">Forgot Password</CardTitle>
				<CardDescription>
					Enter your email address and we'll send you a link to reset your
					password.
				</CardDescription>
			</CardHeader>
			<CardContent>
				<form onSubmit={handleSubmit} className="space-y-4">
					<FormField
						label="Email"
						type="email"
						placeholder="you@example.com"
						value={email}
						onChange={setEmail}
						error={error}
						required
					/>
					<Button type="submit" className="w-full" disabled={!email || isSubmitting}>
						{isSubmitting ? "Sending..." : "Send Reset Link"}
					</Button>
					<Link href="/sign-in" as={never} className="block">
						<Button type="button" variant="ghost" className="w-full">
							Cancel
						</Button>
					</Link>
				</form>
			</CardContent>
		</Card>
	);
}

