"use client";

import Link from "next/link";
import { CheckCircle2, XCircle } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { authClient } from "@/lib/auth-client";
import {
	Card,
	CardContent,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import Loader from "@/components/loader";

type VerifyState = "loading" | "success" | "error";

export default function VerifyEmailPage() {
	const router = useRouter();
	const searchParams = useSearchParams();
	const token = searchParams.get("token");
	const [state, setState] = useState<VerifyState>("loading");
	const [errorMessage, setErrorMessage] = useState<string>("");

	useEffect(() => {
		if (!token) {
			setState("error");
			setErrorMessage("No verification token provided.");
			return;
		}

		authClient.verifyEmail(
			{ query: { token } },
			{
				onSuccess: () => {
					setState("success");
					toast.success("Email verified successfully");
				},
				onError: (ctx: { error: { message?: string } }) => {
					setState("error");
					setErrorMessage(
						ctx.error.message || "Failed to verify email. The link may be expired or invalid.",
					);
					toast.error(ctx.error.message || "Failed to verify email");
				},
			},
		);
	}, [token]);

	if (state === "loading") {
		return (
			<Card>
				<CardContent className="flex items-center justify-center py-12">
					<Loader />
				</CardContent>
			</Card>
		);
	}

	if (state === "success") {
		return (
			<Card>
				<CardHeader className="text-center">
					<div className="flex justify-center">
						<CheckCircle2 className="text-success size-12" />
					</div>
					<CardTitle className="mt-4">Email Verified</CardTitle>
					<CardDescription>
						Your email has been successfully verified. You can now access all
						features of your account.
					</CardDescription>
				</CardHeader>
				<CardContent className="space-y-4">
					<Link href="/settings" as={never} className="block">
						<Button className="w-full">Go to Settings</Button>
					</Link>
				</CardContent>
			</Card>
		);
	}

	return (
		<Card>
			<CardHeader className="text-center">
				<div className="flex justify-center">
					<XCircle className="text-destructive size-12" />
				</div>
				<CardTitle className="mt-4">Verification Failed</CardTitle>
				<CardDescription>{errorMessage}</CardDescription>
			</CardHeader>
			<CardContent className="space-y-4">
				<Link href="/settings" as={never} className="block">
					<Button variant="outline" className="w-full">
						Back to Settings
					</Button>
				</Link>
			</CardContent>
		</Card>
	);
}

