"use client";

import Link from "next/link";
import { Lock } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";
import { toast } from "sonner";
import z from "zod";

import { authClient } from "@/lib/auth-client";
import { FormField } from "@/components/forms/form-field";
import {
	Card,
	CardContent,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import Loader from "@/components/loader";

export default function ResetPasswordPage() {
	const router = useRouter();
	const searchParams = useSearchParams();
	const token = searchParams.get("token");

	const [password, setPassword] = useState("");
	const [confirmPassword, setConfirmPassword] = useState("");
	const [isSubmitting, setIsSubmitting] = useState(false);
	const [errors, setErrors] = useState<{ password?: string; confirm?: string }>({});
	const [generalError, setGeneralError] = useState("");

	const handleSubmit = async (e: React.FormEvent) => {
		e.preventDefault();
		setErrors({});
		setGeneralError("");

		// Validate passwords
		const passwordSchema = z
			.string()
			.min(8, "Password must be at least 8 characters");

		const passwordResult = passwordSchema.safeParse(password);
		if (!passwordResult.success) {
			setErrors({ password: passwordResult.error.issues[0].message });
			return;
		}

		if (password !== confirmPassword) {
			setErrors({ confirm: "Passwords do not match" });
			return;
		}

		if (!token) {
			setGeneralError("Invalid or expired reset token. Please request a new one.");
			return;
		}

		setIsSubmitting(true);

		await authClient.resetPassword(
			{ newPassword: password, token },
			{
				onSuccess: () => {
					toast.success("Password reset successfully");
					router.push("/sign-in" as never);
				},
				onError: (ctx: { error: { message?: string } }) => {
					setGeneralError(
						ctx.error.message ||
							"Failed to reset password. The link may be expired.",
					);
					toast.error(ctx.error.message || "Failed to reset password");
				},
			},
		);

		setIsSubmitting(false);
	};

	if (isSubmitting) {
		return (
			<Card>
				<CardContent className="flex items-center justify-center py-12">
					<Loader />
				</CardContent>
			</Card>
		);
	}

	return (
		<Card>
			<CardHeader>
				<div className="flex justify-center">
					<Lock className="text-muted-foreground size-12" />
				</div>
				<CardTitle className="mt-4 text-center text-2xl">
					Reset Password
				</CardTitle>
				<CardDescription className="text-center">
					Enter your new password below.
				</CardDescription>
			</CardHeader>
			<CardContent>
				<form onSubmit={handleSubmit} className="space-y-4">
					<FormField
						label="New Password"
						type="password"
						placeholder="••••••••"
						value={password}
						onChange={setPassword}
						error={errors.password}
						required
					/>
					<FormField
						label="Confirm Password"
						type="password"
						placeholder="••••••••"
						value={confirmPassword}
						onChange={setConfirmPassword}
						error={errors.confirm}
						required
					/>
					{generalError && (
						<p className="text-destructive text-sm">{generalError}</p>
					)}
					<Button
						type="submit"
						className="w-full"
						disabled={!password || !confirmPassword || isSubmitting}
					>
						{isSubmitting ? "Resetting..." : "Reset Password"}
					</Button>
					<Link href="/sign-in" as={never} className="block">
						<Button type="button" variant="ghost" className="w-full">
							Cancel
						</Button>
					</Link>
				</form>
			</CardContent>
		</Card>
	);
}

